import{_ as a,o as e,c as l,ag as n}from"./chunks/framework.CU0NaXTj.js";const r="/assets/agent-architecture.DHxQZCAU.png",s="/assets/mcp-protocol.BCHqF2Qr.png",u=JSON.parse('{"title":"从 LLM 到 Agent Skill：底层逻辑完全指南","description":"","frontmatter":{"title":"从 LLM 到 Agent Skill：底层逻辑完全指南","date":"2026-03-24T00:00:00.000Z","permalink":"/pages/ai-guide/","categories":["AI"],"tags":["LLM","Agent","Skill","MCP","OpenClaw"]},"headers":[],"relativePath":"03.AI/01.llm-agent-skill-guide.md","filePath":"03.AI/01.llm-agent-skill-guide.md","lastUpdated":1774420720000}'),o={name:"03.AI/01.llm-agent-skill-guide.md"};function i(d,t,h,p,c,g){return e(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="从-llm-到-agent-skill-底层逻辑完全指南" tabindex="-1">从 LLM 到 Agent Skill：底层逻辑完全指南 <a class="header-anchor" href="#从-llm-到-agent-skill-底层逻辑完全指南" aria-label="Permalink to &quot;从 LLM 到 Agent Skill：底层逻辑完全指南&quot;">​</a></h1><blockquote><p>📌 通俗易懂的概念解析，帮你打通 AI 智能体的任督二脉</p></blockquote><blockquote><p>📺 <strong>参考视频</strong>：<a href="https://b23.tv/o2qWoPt" target="_blank" rel="noreferrer">一个视频了解 agent 什么是 agent？什么是 mcp？什么是 tools？什么是 skills？</a> - Bilibili</p></blockquote><hr><h2 id="一、核心概念速览" tabindex="-1">一、核心概念速览 <a class="header-anchor" href="#一、核心概念速览" aria-label="Permalink to &quot;一、核心概念速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>定义</th><th>角色</th><th>例子</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>Large Language Model（大语言模型）</td><td>大脑</td><td>GPT-4、Claude、Qwen</td></tr><tr><td><strong>Agent</strong></td><td>LLM + 工具 + 记忆 + 自主性</td><td>完整的人</td><td>OpenClaw、AutoGPT</td></tr><tr><td><strong>Skill</strong></td><td>封装好的工具/能力包</td><td>手脚</td><td>weather-skill、browser-skill</td></tr><tr><td><strong>MCP</strong></td><td>Model Context Protocol（模型上下文协议）</td><td>协议标准</td><td>MCP Server 规范</td></tr></tbody></table><hr><h2 id="二、llm-能思考但不能行动" tabindex="-1">二、LLM：能思考但不能行动 <a class="header-anchor" href="#二、llm-能思考但不能行动" aria-label="Permalink to &quot;二、LLM：能思考但不能行动&quot;">​</a></h2><p><strong>LLM = 读过全世界书籍的超级学霸</strong></p><h3 id="_1-能做什么" tabindex="-1">1. 能做什么 <a class="header-anchor" href="#_1-能做什么" aria-label="Permalink to &quot;1. 能做什么&quot;">​</a></h3><ul><li>写文章、回答问题、翻译、写代码、总结</li></ul><h3 id="_2-不能做什么" tabindex="-1">2. 不能做什么 <a class="header-anchor" href="#_2-不能做什么" aria-label="Permalink to &quot;2. 不能做什么&quot;">​</a></h3><ul><li>❌ 访问实时信息（不知道今天的天气）</li><li>❌ 操作外部工具（不能帮你发邮件）</li><li>❌ 执行代码（写的代码需要人来运行）</li></ul><blockquote><p>🎭 <strong>比喻</strong>：LLM 就像一个被关在房间里的智者，知识渊博但不能出门、不能用手机。</p></blockquote><hr><h2 id="三、agent-llm-的完全体" tabindex="-1">三、Agent：LLM 的完全体 <a class="header-anchor" href="#三、agent-llm-的完全体" aria-label="Permalink to &quot;三、Agent：LLM 的完全体&quot;">​</a></h2><p><strong>Agent = LLM + 工具 + 记忆 + 自主性</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Agent (智能体)              │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│  🧠 大脑：LLM（理解和决策）              │</span></span>
<span class="line"><span>│  🛠️ 双手：Tools（执行能力）              │</span></span>
<span class="line"><span>│  📝 记忆：Memory（短期 + 长期记忆）       │</span></span>
<span class="line"><span>│  🔄 循环：感知 → 思考 → 行动 → 反馈      │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>Agent 能做什么（LLM 做不到的）</strong>：</p><ul><li>查实时信息、操作工具、执行代码、多步任务、长期记忆</li></ul><blockquote><p>🦸 <strong>比喻</strong>：Agent = 智慧 + 战衣（工具）+ 基地（记忆）+ 任务（目标）</p></blockquote><hr><h2 id="四、skill-即插即用的能力包" tabindex="-1">四、Skill：即插即用的能力包 <a class="header-anchor" href="#四、skill-即插即用的能力包" aria-label="Permalink to &quot;四、Skill：即插即用的能力包&quot;">​</a></h2><p><strong>Skill = 封装好的工具/能力包</strong></p><table tabindex="0"><thead><tr><th>Skill 名称</th><th>功能</th><th>使用场景</th></tr></thead><tbody><tr><td><code>weather</code></td><td>查天气</td><td>用户问天气时自动调用</td></tr><tr><td><code>web_search</code></td><td>搜索网络</td><td>需要实时信息时调用</td></tr><tr><td><code>browser</code></td><td>控制浏览器</td><td>需要操作网页时调用</td></tr></tbody></table><blockquote><p>🎮 <strong>比喻</strong>：Skill 就像游戏里的技能书，捡到《火球术》→ 学会放火球，捡到 <code>weather</code> Skill → 学会查天气。</p></blockquote><hr><h2 id="五、mcp-统一接口标准" tabindex="-1">五、MCP：统一接口标准 <a class="header-anchor" href="#五、mcp-统一接口标准" aria-label="Permalink to &quot;五、MCP：统一接口标准&quot;">​</a></h2><p><strong>MCP = Model Context Protocol（模型上下文协议）</strong></p><p>把 MCP 想象成 <strong>USB-C 接口标准</strong>：</p><ul><li>🔌 之前：每个工具都有自己的接口，适配成本高</li><li>📦 之后：所有工具统一接口，即插即用</li></ul><h3 id="_1-mcp-核心概念" tabindex="-1">1. MCP 核心概念 <a class="header-anchor" href="#_1-mcp-核心概念" aria-label="Permalink to &quot;1. MCP 核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td><strong>MCP Host</strong></td><td>运行 MCP 客户端的程序</td><td>OpenClaw、Claude Desktop</td></tr><tr><td><strong>MCP Server</strong></td><td>提供数据/工具的服务</td><td>天气 MCP Server、文件系统 MCP Server</td></tr><tr><td><strong>Resources</strong></td><td>只读数据源</td><td>文件内容、数据库记录</td></tr><tr><td><strong>Tools</strong></td><td>可执行的操作</td><td>发送邮件、创建文件</td></tr></tbody></table><h3 id="_2-mcp-vs-skill" tabindex="-1">2. MCP vs Skill <a class="header-anchor" href="#_2-mcp-vs-skill" aria-label="Permalink to &quot;2. MCP vs Skill&quot;">​</a></h3><p><strong>一句话</strong>：MCP 是协议标准，Skill 是具体实现</p><ul><li><strong>MCP</strong> = USB-C 接口规范（统一标准）</li><li><strong>Skill</strong> = 具体的 USB 设备（U 盘、充电器）</li></ul><h3 id="_3-mcp-vs-function-calling" tabindex="-1">3. MCP vs Function Calling <a class="header-anchor" href="#_3-mcp-vs-function-calling" aria-label="Permalink to &quot;3. MCP vs Function Calling&quot;">​</a></h3><ul><li><strong>Function Calling</strong> = 打电话的动作（怎么调用）</li><li><strong>MCP</strong> = 电话网络协议（怎么找到并连接）</li></ul><hr><h2 id="六、四者关系总结" tabindex="-1">六、四者关系总结 <a class="header-anchor" href="#六、四者关系总结" aria-label="Permalink to &quot;六、四者关系总结&quot;">​</a></h2><blockquote><p><strong>LLM 是大脑，Skill 是手脚，Agent 是完整的人</strong></p></blockquote><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 → Agent（决策中枢）→ Skills（天气/搜索/邮件）→ LLM（理解/生成）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>概念</th><th>角色</th><th>能做什么</th><th>不能做什么</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>大脑</td><td>理解、推理、生成文本</td><td>不能执行、不能记忆</td></tr><tr><td><strong>Skill</strong></td><td>手脚</td><td>执行具体任务</td><td>不能自主决策</td></tr><tr><td><strong>Agent</strong></td><td>完整的人</td><td>感知→思考→行动→反馈</td><td>受限于配置的 Skills</td></tr></tbody></table><p><strong>记忆口诀</strong>：</p><ul><li>🧠 <strong>LLM 动脑不动手</strong></li><li>🔧 <strong>Skill 动手不动脑</strong></li><li>🤖 <strong>Agent 动脑又动手</strong></li></ul><hr><h2 id="七、架构图解" tabindex="-1">七、架构图解 <a class="header-anchor" href="#七、架构图解" aria-label="Permalink to &quot;七、架构图解&quot;">​</a></h2><h3 id="_1-agent-架构图" tabindex="-1">1. Agent 架构图 <a class="header-anchor" href="#_1-agent-架构图" aria-label="Permalink to &quot;1. Agent 架构图&quot;">​</a></h3><p><img src="`+r+'" alt="Agent 架构图"></p><blockquote><p>Agent 的核心组成：LLM 提供智能决策，Skills 封装能力知识，MCP 提供标准化接口，Tools 执行具体操作。</p></blockquote><h3 id="_2-mcp-模型上下文协议" tabindex="-1">2. MCP 模型上下文协议 <a class="header-anchor" href="#_2-mcp-模型上下文协议" aria-label="Permalink to &quot;2. MCP 模型上下文协议&quot;">​</a></h3><p><img src="'+s+'" alt="MCP 模型上下文协议"></p><blockquote><p>MCP（Model Context Protocol）是连接 AI 与外部服务的统一协议标准，实现即插即用的工具生态。</p></blockquote><hr><h2 id="八、延伸阅读" tabindex="-1">八、延伸阅读 <a class="header-anchor" href="#八、延伸阅读" aria-label="Permalink to &quot;八、延伸阅读&quot;">​</a></h2><h3 id="参考视频" tabindex="-1">参考视频 <a class="header-anchor" href="#参考视频" aria-label="Permalink to &quot;参考视频&quot;">​</a></h3><ul><li><a href="https://b23.tv/o2qWoPt" target="_blank" rel="noreferrer">一个视频了解 agent 什么是 agent？什么是 mcp？什么是 tools？什么是 skills？</a> - Bilibili</li><li><a href="https://b23.tv/video/BV1ojfDBSEPv" target="_blank" rel="noreferrer">一口气拆穿 Skill/MCP/RAG/Agent/OpenClaw 底层逻辑</a> - Bilibili</li></ul><h3 id="文档资源" tabindex="-1">文档资源 <a class="header-anchor" href="#文档资源" aria-label="Permalink to &quot;文档资源&quot;">​</a></h3><ul><li>OpenClaw 中文文档：<a href="https://docs.openclaw.ai/zh-CN" target="_blank" rel="noreferrer">https://docs.openclaw.ai/zh-CN</a></li><li>MCP 官方规范：<a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">https://modelcontextprotocol.io</a></li></ul><hr><p><em>📌 本文档由 OpenClaw 小钉 生成 | 最后更新：2026-03-24</em></p>',61)])])}const k=a(o,[["render",i]]);export{u as __pageData,k as default};
